import{_ as o,o as r,c as a,a5 as n}from"./chunks/framework.Bt0SrEfo.js";const g=JSON.parse('{"title":"六、三面准备（友邦 AIA）","description":"","frontmatter":{},"headers":[],"relativePath":"副业/保险展业/06-三面准备.md","filePath":"副业/保险展业/06-三面准备.md","lastUpdated":1792553737000}'),e={name:"副业/保险展业/06-三面准备.md"};function d(l,t,s,u,h,i){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六、三面准备-友邦-aia" tabindex="-1">六、三面准备（友邦 AIA） <a class="header-anchor" href="#六、三面准备-友邦-aia" aria-label="Permalink to &quot;六、三面准备（友邦 AIA）&quot;">​</a></h1><blockquote><p>本篇是<strong>打友邦三面的作战手册</strong>。 三面由团队主管（SSC）面，评分表会逐项打&quot;差 / 一般 / 强&quot;。 这篇先拆解评分表，再给 7 道题的答法、话术和填空位。</p></blockquote><hr><h2 id="_1-先看懂评分表-主管在打什么分" tabindex="-1">1. 先看懂评分表：主管在打什么分 <a class="header-anchor" href="#_1-先看懂评分表-主管在打什么分" aria-label="Permalink to &quot;1. 先看懂评分表：主管在打什么分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>板块</th><th>能不能改</th><th>主管真正在看什么</th></tr></thead><tbody><tr><td>概貌 · 硬件</td><td>❌ 改不了</td><td>年龄 / 学历 / 过往收入 / 人脉资源 —— 只是<strong>门槛筛</strong>，权重低，不靠这里拿分</td></tr><tr><td>概貌 · 软件</td><td>✅ 能证明</td><td>企图心、可教性、交际能力、表达能力、亲和力</td></tr><tr><td>优增过程 · 状态记录</td><td>✅ 能证明</td><td>态度：学习投入、目标感、客户开拓计划、<strong>家庭支持度</strong></td></tr></tbody></table><h3 id="三条潜台词-比题目本身更重要" tabindex="-1">三条潜台词（比题目本身更重要） <a class="header-anchor" href="#三条潜台词-比题目本身更重要" aria-label="Permalink to &quot;三条潜台词（比题目本身更重要）&quot;">​</a></h3><ol><li><p><strong>主管在算一笔账</strong>：培养一个新人 3–6 个月，我的时间成本能不能赚回来？ 所以他不是想听你说&quot;我很有热情&quot;，他想听&quot;<strong>你具体打算怎么干</strong>&quot;。</p></li><li><p><strong>&quot;差 / 一般 / 强&quot;里，&quot;一般&quot;是安全线，不是好结果。</strong> 硬件你已经定了，唯一能翻盘的板块是<strong>可教性 + 亲和力 + 状态记录</strong>。 这三项就是你的战场。</p></li><li><p><strong>最大的隐藏扣分项：没有数字。</strong> 认识引荐人多久、参加几次活动、三个月收入目标、过去收入 —— 全都要数字化。 说&quot;还在了解阶段&quot;=&quot;差&quot;；说&quot;认识 5 个月，参加过 8 场活动&quot;=&quot;强&quot;。 <strong>含糊 = 差，这是评分表里最容易被忽略的规则。</strong></p></li></ol><blockquote><p>🎯 一句话总结：<strong>每一题都要落到一个可验证的动作，而不是态度表态。</strong></p></blockquote><hr><h2 id="_2-通用原则-三面共通" tabindex="-1">2. 通用原则（三面共通） <a class="header-anchor" href="#_2-通用原则-三面共通" aria-label="Permalink to &quot;2. 通用原则（三面共通）&quot;">​</a></h2><h3 id="三条加分动作" tabindex="-1">三条加分动作 <a class="header-anchor" href="#三条加分动作" aria-label="Permalink to &quot;三条加分动作&quot;">​</a></h3><ul><li><strong>数字优先</strong>：任何能量化的都量化（时间、场次、单量、保费、好友数）</li><li><strong>主动认领挑战</strong>：说&quot;我没有挑战&quot;直接判差。认一个真挑战 + 配应对动作</li><li><strong>反问要具体</strong>：反问环节问出细节，主管会认为你做过功课</li></ul><h3 id="四个禁忌" tabindex="-1">四个禁忌 <a class="header-anchor" href="#四个禁忌" aria-label="Permalink to &quot;四个禁忌&quot;">​</a></h3><table tabindex="0"><thead><tr><th>❌ 不要</th><th>为什么</th></tr></thead><tbody><tr><td>吐槽前公司 / 前领导</td><td>主管会想&quot;你下次也这么说我&quot;</td></tr><tr><td>说&quot;先试试看&quot;&quot;干一段时间再说&quot;</td><td>直接踩&quot;投入度&quot;评分</td></tr><tr><td>说&quot;保险公司都差不多&quot;</td><td>证明你没做功课</td></tr><tr><td>只讲产品收益，不讲客户</td><td>主管不想听产品，他想听你怎么找客户</td></tr></tbody></table><h3 id="形象底线" tabindex="-1">形象底线 <a class="header-anchor" href="#形象底线" aria-label="Permalink to &quot;形象底线&quot;">​</a></h3><ul><li>准时，提前 10 分钟到；手机静音</li><li>主管说话时不要抢话，回答完停一拍，别急着补充</li><li>手机里提前查好&quot;友邦历史 / 主打产品 / 代理人制度&quot;，别现场现搜</li><li>带纸笔：记下主管名字、你主管团队多少人、他的姓名（后面跟进要用）</li></ul><hr><h2 id="_3-第-1-题-请用-2-分钟介绍一下自己" tabindex="-1">3. 第 1 题：请用 2 分钟介绍一下自己 <a class="header-anchor" href="#_3-第-1-题-请用-2-分钟介绍一下自己" aria-label="Permalink to &quot;3. 第 1 题：请用 2 分钟介绍一下自己&quot;">​</a></h2><h3 id="评分点" tabindex="-1">评分点 <a class="header-anchor" href="#评分点" aria-label="Permalink to &quot;评分点&quot;">​</a></h3><p>背景、经历、家庭情况。<strong>差 / 一般 / 强</strong>三档。</p><h3 id="时间控制" tabindex="-1">时间控制 <a class="header-anchor" href="#时间控制" aria-label="Permalink to &quot;时间控制&quot;">​</a></h3><p>2 分钟 ≈ <strong>400–450 字</strong>，口语化，超过 2 分钟会被打断，打断就掉档。</p><h3 id="结构-四段式" tabindex="-1">结构（四段式） <a class="header-anchor" href="#结构-四段式" aria-label="Permalink to &quot;结构（四段式）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>段</th><th>内容</th><th>占比</th></tr></thead><tbody><tr><td>① 身份</td><td>我是谁、现在什么状态</td><td>20s</td></tr><tr><td>② 经历</td><td>工作背景 + <strong>和保险的连接点</strong></td><td>40s</td></tr><tr><td>③ 转折</td><td>为什么在这个时间点做保险</td><td>30s</td></tr><tr><td>④ 价值</td><td>我能带来什么（对应软件评分）</td><td>30s</td></tr></tbody></table><h3 id="话术模板-填空处替换成你的真话" tabindex="-1">话术模板（填空处替换成你的真话） <a class="header-anchor" href="#话术模板-填空处替换成你的真话" aria-label="Permalink to &quot;话术模板（填空处替换成你的真话）&quot;">​</a></h3><blockquote><p>&quot;面试官好，我是 XXX，XX 岁，XX 学历。（<strong>①身份，20 秒</strong>）</p><p>我做前端开发 7 年，主要做 C 端会员平台和 B 端后台 —— 说实话我做的业务里，<strong>充值、提款、风控、活动这些链路，天天都在处理&quot;钱和风险&quot;的问题</strong>，这可能是我后来关注保障的一个起点。（<strong>②经历 + 连接点</strong>）</p><p>做技术这几年我发现，我真正有兴趣的不是写代码本身，而是<strong>弄清楚一个家庭、一个企业为什么要在某个点上做决策</strong>。保险刚好是把这件事做到极致的行业。（<strong>③转折</strong>）</p><p>我现在想转，是想用它<strong>把我学到的分析能力和沟通能力用在一个更长周期的服务上</strong>。我不缺学习能力 —— 我这个博客（指手机 / 口头）就是这些年系统学习沉淀的，我会保险是同一套方法。（<strong>④价值，对应&quot;可教性&quot;</strong>）&quot;</p></blockquote><h3 id="关键技巧-技术背景要-硬接-不能-硬转" tabindex="-1">关键技巧：技术背景要&quot;硬接&quot;，不能&quot;硬转&quot; <a class="header-anchor" href="#关键技巧-技术背景要-硬接-不能-硬转" aria-label="Permalink to &quot;关键技巧：技术背景要&quot;硬接&quot;，不能&quot;硬转&quot;&quot;">​</a></h3><p>❌ 错误接法：&quot;我是程序员，代码写得好，学习能力强，所以我能做好销售。&quot; （主管听了 5 秒就知道你在硬转）</p><p>✅ 正确接法：<strong>从业务里找共通性</strong></p><ul><li>处理过用户资金链路 → 理解&quot;风险转移&quot;的底层逻辑</li><li>对接过运营 / 业务方 → 知道怎么跟不熟的人建立信任</li><li>做过多角色沟通 → 抗压、被拒绝的承受力</li></ul><h3 id="家庭情况要不要说" tabindex="-1">家庭情况要不要说？ <a class="header-anchor" href="#家庭情况要不要说" aria-label="Permalink to &quot;家庭情况要不要说？&quot;">​</a></h3><p>评分表写了&quot;家庭情况&quot;，所以<strong>要提</strong>，但一笔带过 + 主动给稳定信号：</p><blockquote><p>&quot;家庭情况比较简单，家里人都支持我做这个决定，这块我在来之前已经沟通过了。&quot;</p></blockquote><p>（说谎或含糊会被追问，坦诚 + 已沟通是最安全解）</p><h3 id="❌-不要说的话" tabindex="-1">❌ 不要说的话 <a class="header-anchor" href="#❌-不要说的话" aria-label="Permalink to &quot;❌ 不要说的话&quot;">​</a></h3><ul><li>❌ &quot;我最近工作不太顺 / 想换个环境&quot;（把动机说成逃避）</li><li>❌ 背技术栈（React、Vue、TypeScript……主管不关心）</li><li>❌ 说超过 2 分钟</li><li>❌ 说&quot;我觉得保险很有前景&quot;（空话）</li></ul><hr><h2 id="_4-第-2-题-你和引荐人怎么认识的-多久了-参加过多少次活动" tabindex="-1">4. 第 2 题：你和引荐人怎么认识的？多久了？参加过多少次活动？ <a class="header-anchor" href="#_4-第-2-题-你和引荐人怎么认识的-多久了-参加过多少次活动" aria-label="Permalink to &quot;4. 第 2 题：你和引荐人怎么认识的？多久了？参加过多少次活动？&quot;">​</a></h2><h3 id="评分点-1" tabindex="-1">评分点 <a class="header-anchor" href="#评分点-1" aria-label="Permalink to &quot;评分点&quot;">​</a></h3><p><strong>投入度的直接证据</strong>。这题主管几乎不用听内容，只看<strong>数字和细节</strong>。</p><h3 id="必备三个数字" tabindex="-1">必备三个数字 <a class="header-anchor" href="#必备三个数字" aria-label="Permalink to &quot;必备三个数字&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数字</th><th>为什么</th></tr></thead><tbody><tr><td>认识引荐人多久了</td><td>判断你是不是认真进了这个门</td></tr><tr><td>参加过多少次活动</td><td>判断你有没有持续投入</td></tr><tr><td>最深刻的一次活动</td><td>判断你有没有在<strong>观察和思考</strong></td></tr></tbody></table><blockquote><p>⚠️ 填空前先数清楚。参加过 6 场，就说 6 场，<strong>别说&quot;好几场&quot;</strong>。 数字对不上，主管追问细节你就崩了。</p></blockquote><h3 id="话术模板" tabindex="-1">话术模板 <a class="header-anchor" href="#话术模板" aria-label="Permalink to &quot;话术模板&quot;">​</a></h3><blockquote><p>&quot;我是通过（<strong>引荐人姓名/身份</strong>）认识的，认识的第（<strong>X</strong>）个月他/她就带我来参加活动。</p><p>前前后后参加了（<strong>X</strong>）场，（<strong>列举 1-2 个活动名称</strong>）。</p><p>印象最深的是（<strong>第 X 场</strong>），原因是……（<strong>重点，见下</strong>）&quot;</p></blockquote><h3 id="印象最深刻-怎么讲出高级感" tabindex="-1">&quot;印象最深刻&quot;怎么讲出高级感？ <a class="header-anchor" href="#印象最深刻-怎么讲出高级感" aria-label="Permalink to &quot;&quot;印象最深刻&quot;怎么讲出高级感？&quot;">​</a></h3><p>❌ 平庸答法：</p><blockquote><p>&quot;参加了 XX 的品鉴会，氛围很好，讲解很专业，感觉挺不错的。&quot;</p></blockquote><p>（= &quot;一般&quot;，没有信息量）</p><p>✅ 拔高答法：<strong>讲你的观察 + 结论 + 后续动作</strong></p><blockquote><p>&quot;印象最深的是第（<strong>X</strong>）场（<strong>活动名</strong>）。我当时观察到一个细节 —— 来的多半是企业主和中产家庭， 他们坐下之后问的第一句话不是&#39;收益多少&#39;，而是&#39;<strong>我要是出事了怎么办</strong>&#39;。</p><p>这个观察对我冲击挺大的：我做技术时习惯假设&#39;最坏情况是可恢复的&#39;， 但对一个家庭来说，最坏情况是不可逆的。那场之后我就开始补保险的功課 —— 条款、责任免除、现金价值这些。</p><p>现在我能讲清楚&#39;重疾和医疗的区别&#39;、&#39;为什么要先保大人再保小孩&#39;，这是我真实学进去的东西。&quot;</p></blockquote><blockquote><p>🎯 为什么这样讲加分？ ① 证明你<strong>在现场做观察</strong>，不是去蹭饭的 ② 证明你<strong>回去做了功课</strong>（对应&quot;可教性&quot;） ③ 提到责任免除、现金价值这种<strong>专业词</strong>，主管会立刻给你加&quot;强&quot;</p></blockquote><hr><h2 id="_5-第-3-题-介绍一下你了解的友邦-哪些吸引你-为什么想来" tabindex="-1">5. 第 3 题：介绍一下你了解的友邦，哪些吸引你，为什么想来？ <a class="header-anchor" href="#_5-第-3-题-介绍一下你了解的友邦-哪些吸引你-为什么想来" aria-label="Permalink to &quot;5. 第 3 题：介绍一下你了解的友邦，哪些吸引你，为什么想来？&quot;">​</a></h2><h3 id="评分点-2" tabindex="-1">评分点 <a class="header-anchor" href="#评分点-2" aria-label="Permalink to &quot;评分点&quot;">​</a></h3><p>对友邦的了解。<strong>这题最容易问穿，必须做足功课。</strong></p><h3 id="🚨-上场前必做的功课-30-分钟" tabindex="-1">🚨 上场前必做的功课（30 分钟） <a class="header-anchor" href="#🚨-上场前必做的功课-30-分钟" aria-label="Permalink to &quot;🚨 上场前必做的功课（30 分钟）&quot;">​</a></h3><p>去 <a href="https://www.aia.com.cn" target="_blank" rel="noreferrer">aia.com.cn</a> 或官方渠道，把下面这些<strong>抄成数字</strong>背下来：</p><table tabindex="0"><thead><tr><th>#</th><th>要准备的</th><th>备注</th></tr></thead><tbody><tr><td>1</td><td>友邦创立年份、发源地</td><td>常被问的历史题</td></tr><tr><td>2</td><td>进入中国内地市场的时间、第一家机构</td><td>别说成其他年份</td></tr><tr><td>3</td><td>品牌口号</td><td>「<strong>健康长久好生活</strong>」——这句你标题里就有，要能讲出含义</td></tr><tr><td>4</td><td>主打产品线（重疾 / 医疗 / 长期储蓄 / 传承）</td><td>说得出 2-3 条</td></tr><tr><td>5</td><td>代理人制度特点</td><td>和同业&quot;底薪+提成&quot;有什么不同</td></tr><tr><td>6</td><td>荣誉体系（MDRT / 会员等级）</td><td>证明你知道这条路能走多远</td></tr></tbody></table><blockquote><p>⚠️ 年份、产品名这类事实<strong>以你自己查到的官方信息为准</strong>， 不要用网上二手文章的说法，主管一问细节就知道你只是&quot;刷到过&quot;。</p></blockquote><h3 id="话术模板-1" tabindex="-1">话术模板 <a class="header-anchor" href="#话术模板-1" aria-label="Permalink to &quot;话术模板&quot;">​</a></h3><blockquote><p>&quot;我了解的友邦是（<strong>成立时间/发源地，一句话</strong>）， 进入内地是（<strong>年份</strong>），品牌主张是「<strong>健康长久好生活</strong>」。</p><p>吸引我的是两点：</p><p><strong>第一，这句话本身。</strong>「健康长久好生活」不是单纯卖保障 —— 前两个词是<strong>当下</strong>， 第三个词是<strong>长期</strong>。我觉得这说明产品设计会往长周期走，而不是靠短期理财做销量。这跟我的想法是一致的。（<strong>把口号翻译成业务理解 —— 这是&quot;强&quot;的答案</strong>）</p><p><strong>第二，代理人这个职业。</strong>（<strong>这里接第 6 题你的真实优势</strong>）我觉得它不是一份坐办公室的工， 而是需要长期经营关系的工，这个角色吸引我。</p><p>我为什么想来：我想清楚了两件事 —— <strong>这个行业的价值是真的</strong>，我身边确实有家庭因为没有保障而出问题； <strong>我要做，就做好。</strong>（<strong>对应&quot;企图心&quot;</strong>）</p><p>为了不来做一名&#39;问熟人买保险就完事&#39;的代理人，我（<strong>已参加 X 场活动 / 已系统学了 XX / 正在做 XX</strong>）。&quot;</p></blockquote><h3 id="❌-这题的死亡回答" tabindex="-1">❌ 这题的死亡回答 <a class="header-anchor" href="#❌-这题的死亡回答" aria-label="Permalink to &quot;❌ 这题的死亡回答&quot;">​</a></h3><ul><li>❌ &quot;友邦是世界五百强&quot;（空话，任何人都能说）</li><li>❌ &quot;友邦的保险挺便宜的&quot;</li><li>❌ &quot;保险行业前景很好&quot;（没有一句是你自己的判断）</li><li>❌ 把友邦说成其他公司（把友邦的制度和别家混着说 = 露馅）</li></ul><hr><h2 id="_6-第-4-题-你怎么看待保险销售-你的优势是什么-最大的挑战是什么" tabindex="-1">6. 第 4 题：你怎么看待保险销售？你的优势是什么？最大的挑战是什么？ <a class="header-anchor" href="#_6-第-4-题-你怎么看待保险销售-你的优势是什么-最大的挑战是什么" aria-label="Permalink to &quot;6. 第 4 题：你怎么看待保险销售？你的优势是什么？最大的挑战是什么？&quot;">​</a></h2><h3 id="评分点-3" tabindex="-1">评分点 <a class="header-anchor" href="#评分点-3" aria-label="Permalink to &quot;评分点&quot;">​</a></h3><p>对保险工作的了解 + <strong>对自己的了解</strong>。这题在测&quot;清醒度&quot;。</p><h3 id="观点层-先给一个干净的认知" tabindex="-1">观点层：先给一个干净的认知 <a class="header-anchor" href="#观点层-先给一个干净的认知" aria-label="Permalink to &quot;观点层：先给一个干净的认知&quot;">​</a></h3><blockquote><p>&quot;我觉得保险销售的本质不是&#39;卖产品&#39;，是<strong>帮一个家庭把它承担不了的最坏情况转移出去</strong>。</p><p>很多人买保险不是因为觉得保险公司好，是因为他们知道自己扛不住那个风险。 所以代理人真正的价值是：<strong>让客户在没出事的时候也愿意做这个决定。</strong>&quot;</p></blockquote><blockquote><p>🎯 这段话的作用：把&quot;销售&quot;重新定义为&quot;专业服务&quot;。 主管听到的就是&quot;这人理解这行的本质，不是来捞钱的&quot;。</p></blockquote><h3 id="优势层-只挑-3-个-且必须对着评分表说" tabindex="-1">优势层：只挑 3 个，且必须对着评分表说 <a class="header-anchor" href="#优势层-只挑-3-个-且必须对着评分表说" aria-label="Permalink to &quot;优势层：只挑 3 个，且必须对着评分表说&quot;">​</a></h3><p>评分表软件项是：<strong>企图心 / 可教性 / 交际能力、表达能力 / 亲和力</strong>。你挑 3 个说透：</p><table tabindex="0"><thead><tr><th>你的标签</th><th>讲法</th></tr></thead><tbody><tr><td><strong>可教性</strong></td><td>我系统学习能力强（用博客 / 考过什么 / 自学过什么做证据）</td></tr><tr><td><strong>交际能力</strong></td><td>我做过对外对接，能跟不熟的人建立信任（前端对接业务方的例子）</td></tr><tr><td><strong>表达能力</strong></td><td>我长期做技术讲解和方案汇报，把复杂的事讲清楚是我的强项</td></tr></tbody></table><blockquote><p>⚠️ <strong>不要一次说 5 个优势</strong>。主管记不住，只会觉得你在背稿。说 3 个，每个给一个具体证据。</p></blockquote><h3 id="挑战层-这是本题得分点" tabindex="-1">挑战层：<strong>这是本题得分点</strong> <a class="header-anchor" href="#挑战层-这是本题得分点" aria-label="Permalink to &quot;挑战层：**这是本题得分点**&quot;">​</a></h3><p>评分表明确写&quot;最大的挑战会是什么&quot;。说&quot;没有挑战&quot;直接判差。</p><blockquote><p>✅ 三段式挑战答法： <strong>认一个真挑战 → 说清它难在哪 → 说我打算怎么应对</strong></p></blockquote><blockquote><p>&quot;我预判最大的挑战是<strong>前期的从 0 开始</strong>。</p><p>我做技术时是靠系统训练和有标准答案的考题， 但拓客没有标准答案 —— 被拒绝是常态，而且很可能连拒绝都拿不到，只是一句&#39;暂时不需要&#39;。</p><p>我对这个有两个准备： 一是<strong>降低对拒绝的敏感度</strong> —— 我准备把前三个月的每一次拒绝都当成数据记录，做复盘； 二是<strong>先跑量再跑质</strong> —— 我给自己定了（<strong>具体数字</strong>）的月均面谈目标， 用面谈量把成交率这个变量稀释掉。&quot;</p></blockquote><h3 id="可替换的挑战-选一个你真认同的" tabindex="-1">可替换的挑战（选一个你真认同的） <a class="header-anchor" href="#可替换的挑战-选一个你真认同的" aria-label="Permalink to &quot;可替换的挑战（选一个你真认同的）&quot;">​</a></h3><ul><li><strong>收入前期的波动</strong>：从确定工资到佣金制，需要缓冲</li><li><strong>被拒绝的心理关</strong>：开口求人是最难的一步</li><li><strong>从熟人到陌生</strong>：熟人市场是有限的，长期要建立陌生信任</li><li><strong>专业知识门槛</strong>：保险、税务、法律、医学都要懂</li></ul><h3 id="❌-不要说的话-1" tabindex="-1">❌ 不要说的话 <a class="header-anchor" href="#❌-不要说的话-1" aria-label="Permalink to &quot;❌ 不要说的话&quot;">​</a></h3><ul><li>❌ &quot;我的挑战是……我觉得应该没什么挑战&quot;（= 差）</li><li>❌ &quot;我最大的挑战是我不够有钱&quot;（暴露动机不纯）</li><li>❌ 只说挑战不说应对（说完必须接&quot;我打算……&quot;）</li></ul><hr><h2 id="_7-第-5-题-三个月收入目标怎么设定-做好了准备吗" tabindex="-1">7. 第 5 题：三个月收入目标怎么设定？做好了准备吗？ <a class="header-anchor" href="#_7-第-5-题-三个月收入目标怎么设定-做好了准备吗" aria-label="Permalink to &quot;7. 第 5 题：三个月收入目标怎么设定？做好了准备吗？&quot;">​</a></h2><h3 id="评分点-4" tabindex="-1">评分点 <a class="header-anchor" href="#评分点-4" aria-label="Permalink to &quot;评分点&quot;">​</a></h3><p><strong>目标感、投入度。本场权重最高的一题。</strong></p><blockquote><p>🎯 主管在这里做最后的判断：<strong>你是&quot;来玩票的&quot;，还是&quot;来换赛道的&quot;。</strong> 他能听出来 —— 有数字、有拆解、有准备的人是认真的。</p></blockquote><h3 id="目标怎么定-三档法-最稳妥" tabindex="-1">目标怎么定：三档法（最稳妥） <a class="header-anchor" href="#目标怎么定-三档法-最稳妥" aria-label="Permalink to &quot;目标怎么定：三档法（最稳妥）&quot;">​</a></h3><p>只报一个数字，要么显得飘，要么显得不认真。报三档：</p><table tabindex="0"><thead><tr><th>档位</th><th>目标</th><th>作用</th></tr></thead><tbody><tr><td><strong>保底</strong></td><td>（X 单 / X 万保费）</td><td>我清楚最坏情况，也接受</td></tr><tr><td><strong>目标</strong></td><td>（X 单 / X 万保费）</td><td>我真正奔着的</td></tr><tr><td><strong>冲刺</strong></td><td>（X 单 / X 万保费）</td><td>状态好就能摸到</td></tr></tbody></table><blockquote><p>⚠️ 数字自己算，别抄别人的。参考锚点： 三个月大致分 <strong>打底 → 建面谈量 → 转化</strong> 三段。</p></blockquote><h3 id="三个月拆解模板-主管最爱听这个" tabindex="-1">三个月拆解模板（主管最爱听这个） <a class="header-anchor" href="#三个月拆解模板-主管最爱听这个" aria-label="Permalink to &quot;三个月拆解模板（主管最爱听这个）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>收入目标</th><th>关键动作</th></tr></thead><tbody><tr><td><strong>第 1 月</strong></td><td>（保底级）打底</td><td>系统学完产品条款；盘点缘故市场（<strong>列出 X 个人的名单</strong>）；跟引荐人跑（<strong>X</strong>）场活动；每周新增（<strong>X</strong>）个好友</td></tr><tr><td><strong>第 2 月</strong></td><td>（目标级）</td><td>独立参加（<strong>X</strong>）场活动；完成（<strong>X</strong>）次面谈；把面谈记录整理成客户档案</td></tr><tr><td><strong>第 3 月</strong></td><td>（冲刺级）</td><td>集中促成 + 追单；启动转介绍（老客户带新客户）；第一次月度复盘复盘</td></tr></tbody></table><h3 id="是否做好了准备-要答具体" tabindex="-1">&quot;是否做好了准备&quot;要答具体 <a class="header-anchor" href="#是否做好了准备-要答具体" aria-label="Permalink to &quot;&quot;是否做好了准备&quot;要答具体&quot;">​</a></h3><p>❌ &quot;我准备了很多功课&quot;（= 空话 = 一般）</p><p>✅ 分三层说：</p><blockquote><p>&quot;准备分三块：</p><p><strong>知识上</strong> —— 我已经（<strong>自学了什么：条款/重疾医疗区别/责任免除/现金价值</strong>）， 能用大白话讲清楚，不靠术语。</p><p><strong>名单上</strong> —— 我已经列了（<strong>X</strong>）个缘故市场的人， 分了 A/B/C 三类（A 有需求有信任、B 有信任 C 只维护）。（见 <a href="./05-获客转介绍">获客与转介绍</a>）</p><p><strong>节奏上</strong> —— 我下周就会开始（<strong>具体动作：约引荐人一起复盘 / 自己跑一场活动 / 约第一个客户喝咖啡</strong>）， 不是等入职再开始。&quot;</p></blockquote><h3 id="🎯-杀手锏-说出-入职第一天做什么" tabindex="-1">🎯 杀手锏：说出&quot;入职第一天做什么&quot; <a class="header-anchor" href="#🎯-杀手锏-说出-入职第一天做什么" aria-label="Permalink to &quot;🎯 杀手锏：说出&quot;入职第一天做什么&quot;&quot;">​</a></h3><blockquote><p>&quot;如果我通过了，我的第一周会是： <strong>第 1 天</strong>跟主管过一遍我（A/B/C）名单；<strong>第 2–3 天</strong>把前 20 个人的情况电话过一遍； <strong>第 4–5 天</strong>约出第 1 个面谈；<strong>周末</strong>跟引荐人跑一场活动。 一周之内我要有第一次真实面谈。&quot;</p></blockquote><blockquote><p>主管听到这里基本就定了 —— 因为<strong>新人最常见的问题就是&quot;等安排&quot;</strong>， 你说&quot;我第一周就有面谈&quot;，等于告诉他&quot;你不用催我&quot;。</p></blockquote><h3 id="❌-不要说的话-2" tabindex="-1">❌ 不要说的话 <a class="header-anchor" href="#❌-不要说的话-2" aria-label="Permalink to &quot;❌ 不要说的话&quot;">​</a></h3><ul><li>❌ &quot;三个月先保证温饱就行&quot;（目标感=差）</li><li>❌ &quot;我没有具体目标，需要公司给我定&quot;（= 差，直接踩投入度）</li><li>❌ 只说目标不说拆解</li><li>❌ 只说拆解不说准备</li></ul><hr><h2 id="_8-第-6-题-了解保险工作模式吗-怎么开展业务-怎么开拓客户" tabindex="-1">8. 第 6 题：了解保险工作模式吗？怎么开展业务？怎么开拓客户？ <a class="header-anchor" href="#_8-第-6-题-了解保险工作模式吗-怎么开展业务-怎么开拓客户" aria-label="Permalink to &quot;8. 第 6 题：了解保险工作模式吗？怎么开展业务？怎么开拓客户？&quot;">​</a></h2><h3 id="评分点-5" tabindex="-1">评分点 <a class="header-anchor" href="#评分点-5" aria-label="Permalink to &quot;评分点&quot;">​</a></h3><p>客户的开拓能力。<strong>这题考&quot;你能不能落地&quot;。</strong></p><h3 id="工作模式-要说主管的内部语言" tabindex="-1">工作模式（要说主管的内部语言） <a class="header-anchor" href="#工作模式-要说主管的内部语言" aria-label="Permalink to &quot;工作模式（要说主管的内部语言）&quot;">​</a></h3><p>说得出下面的日常，主管就知道你不是外行：</p><table tabindex="0"><thead><tr><th>维度</th><th>我的理解</th></tr></thead><tbody><tr><td><strong>时间</strong></td><td>自主管理，早起安排当天行程；晚间是活动/社交时段</td></tr><tr><td><strong>主线</strong></td><td>活动 + 转介绍 <strong>双轮</strong>：活动获取新面孔，转介绍出高意向</td></tr><tr><td><strong>日常动作</strong></td><td>邀约 → 面谈 → 方案 → 跟进 → 成交 → 转介绍，循环</td></tr><tr><td><strong>核心纪律</strong></td><td>日程不空；每天加好友；每周复盘；每场活动必做跟进</td></tr><tr><td><strong>心理常态</strong></td><td>被拒绝是日常，被当&quot;推销&quot;是日常</td></tr></tbody></table><blockquote><p>&quot;我理解这份工作的常态是<strong>被拒绝</strong>，产出靠的是<strong>稳定的动作量</strong>而不是灵感。 所以我的做法会是：把动作量变成日程表，靠系统出单，而不是靠某一单碰运气。&quot;</p></blockquote><h3 id="客户开拓-分四条渠道-每条给动作和数量" tabindex="-1">客户开拓：分四条渠道 + 每条给动作和数量 <a class="header-anchor" href="#客户开拓-分四条渠道-每条给动作和数量" aria-label="Permalink to &quot;客户开拓：分四条渠道 + 每条给动作和数量&quot;">​</a></h3><p>呼应你博客里的 <a href="./05-获客转介绍">获客与转介绍</a>：</p><table tabindex="0"><thead><tr><th>渠道</th><th>我的第一个月动作</th></tr></thead><tbody><tr><td><strong>缘故市场</strong></td><td>盘点（<strong>X</strong>）个熟人，按 A/B/C 分层；A 类这周就约</td></tr><tr><td><strong>活动获客</strong></td><td>每月参加（<strong>X</strong>）场；每场后 48 小时内跟进全场留资</td></tr><tr><td><strong>社群/线上</strong></td><td>每周发（<strong>X</strong>）条保险相关内容，不刷屏、不群发</td></tr><tr><td><strong>转介绍</strong></td><td>每成交/每服务完一个客户，就自然提一次转介绍（见 <a href="./04-促成成交">促成成交</a>）</td></tr></tbody></table><h3 id="🎯-关键-给出-第一周-的动作清单" tabindex="-1">🎯 关键：给出&quot;第一周&quot;的动作清单 <a class="header-anchor" href="#🎯-关键-给出-第一周-的动作清单" aria-label="Permalink to &quot;🎯 关键：给出&quot;第一周&quot;的动作清单&quot;">​</a></h3><p>主管判断新人靠不靠谱，就看你是不是有<strong>具体的下一步</strong>：</p><blockquote><p>&quot;我的第一个月这样排：</p><ul><li>每周新增好友（<strong>X</strong>）个</li><li>每月参加活动（<strong>X</strong>）场</li><li>每月完成面谈（<strong>X</strong>）次</li><li>每周日晚上做一次复盘：本周见了谁、卡在哪、下周做什么&quot;</li></ul></blockquote><h3 id="❌-不要说的话-3" tabindex="-1">❌ 不要说的话 <a class="header-anchor" href="#❌-不要说的话-3" aria-label="Permalink to &quot;❌ 不要说的话&quot;">​</a></h3><ul><li>❌ &quot;我先在公司学一学再说&quot;（= 差，主管最怕新人&quot;等安排&quot;）</li><li>❌ &quot;主要靠熟人&quot;（主管会问：那熟人用完了怎么办？）</li><li>❌ &quot;我会多发朋友圈&quot;（太低阶，要说内容和频次）</li></ul><hr><h2 id="_9-第-7-题-个性化提问-——-家人支持吗-孩子谁照顾" tabindex="-1">9. 第 7 题：个性化提问 —— 家人支持吗？孩子谁照顾？ <a class="header-anchor" href="#_9-第-7-题-个性化提问-——-家人支持吗-孩子谁照顾" aria-label="Permalink to &quot;9. 第 7 题：个性化提问 —— 家人支持吗？孩子谁照顾？&quot;">​</a></h2><h3 id="评分点-6" tabindex="-1">评分点 <a class="header-anchor" href="#评分点-6" aria-label="Permalink to &quot;评分点&quot;">​</a></h3><p>获得的支持、投入度。<strong>这是最容易翻车的一题，也是最少人准备的一题。</strong></p><h3 id="潜台词" tabindex="-1">潜台词 <a class="header-anchor" href="#潜台词" aria-label="Permalink to &quot;潜台词&quot;">​</a></h3><blockquote><p><strong>&quot;你会不会干两个月，因为家里事就跑了？&quot;</strong></p><p>主管问的不是你家有没有人带娃， 问的是<strong>你有没有把&quot;投入&quot;这件事在家庭层面谈妥</strong>。</p></blockquote><h3 id="🚨-上场前必做-和家里人对齐口径" tabindex="-1">🚨 上场前必做：和家里人对齐口径 <a class="header-anchor" href="#🚨-上场前必做-和家里人对齐口径" aria-label="Permalink to &quot;🚨 上场前必做：和家里人对齐口径&quot;">​</a></h3><p><strong>不要等主管问细节才暴露困难。</strong> 提前和家人明确 4 件事：</p><table tabindex="0"><thead><tr><th>#</th><th>要对齐的事</th><th>为什么</th></tr></thead><tbody><tr><td>1</td><td><strong>收入预期</strong>：前 3-6 个月可能不稳定，家里能不能接受</td><td>这是最容易吵架的点</td></tr><tr><td>2</td><td><strong>社保/医保</strong>：自己交还是继续挂靠，别断缴</td><td>现实问题，主管会认可你想得细</td></tr><tr><td>3</td><td><strong>时间安排</strong>：活动常在晚上/周末，家人怎么配合</td><td>落到具体分工</td></tr><tr><td>4</td><td><strong>孩子照看</strong>：谁接送、谁做饭、谁辅导作业</td><td>主管问的就是这个</td></tr></tbody></table><h3 id="答法-先给结论-再给安排-最后给保障" tabindex="-1">答法：先给结论，再给安排，最后给保障 <a class="header-anchor" href="#答法-先给结论-再给安排-最后给保障" aria-label="Permalink to &quot;答法：先给结论，再给安排，最后给保障&quot;">​</a></h3><blockquote><p>&quot;家里<strong>支持</strong>。（<strong>第一句必须是明确的支持，不能犹豫</strong>）</p><p>具体已经安排好了：</p><ul><li>（<strong>孩子/家人</strong>）这块由（<strong>谁</strong>）负责，接送和作业都已经定下来；</li><li>社保我确认过，会自己（<strong>继续交 / 转灵活就业</strong>），不断缴；</li><li>时间上我清楚保险的作息是<strong>早起 + 晚间/周末活动</strong>，家里也知道这个节奏；</li><li><strong>三个月收入目标我和家里沟通过</strong>，他们知道前期会有一个爬坡期。</li></ul><p>我这边<strong>没有牵绊</strong>，可以全投入。&quot;</p></blockquote><h3 id="为什么这样说有效" tabindex="-1">为什么这样说有效 <a class="header-anchor" href="#为什么这样说有效" aria-label="Permalink to &quot;为什么这样说有效&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你说的</th><th>主管听到的</th></tr></thead><tbody><tr><td>&quot;家里支持&quot;（不犹豫）</td><td>这个人想清楚了，不是头脑发热</td></tr><tr><td>&quot;社保自己交，不断缴&quot;</td><td>他有责任感，不是只想赚快钱</td></tr><tr><td>&quot;目标和家里沟通过&quot;</td><td>他把这件事当成一个正式的决定</td></tr><tr><td>&quot;我没有牵绊&quot;</td><td>我不用担心他中途走</td></tr></tbody></table><h3 id="❌-不要说的话-4" tabindex="-1">❌ 不要说的话 <a class="header-anchor" href="#❌-不要说的话-4" aria-label="Permalink to &quot;❌ 不要说的话&quot;">​</a></h3><ul><li>❌ &quot;家里还不知道&quot;（= 差，直接暴露你还没准备）</li><li>❌ &quot;先干着看，家里有意见再说&quot;（= 差）</li><li>❌ 犹豫、含糊、&quot;这个……其实还好&quot;（主管一听就知道有问题）</li><li>❌ 主动放大困难（&quot;我孩子没人带，可能顾不上&quot;—— 就算真这样， 也要说&quot;我已经安排了 X 来处理&quot;，而不是只抛问题）</li></ul><blockquote><p>⚠️ <strong>万一确实有困难怎么办？</strong> 坦诚 + 已给方案 + 明确边界： &quot;孩子白天由（<strong>谁</strong>）带，晚上和周末我能保证。 这块是我唯一需要协调的，我已经安排好了，不会影响展业时间。&quot; —— 有困难但有解法 = 可信；只抛困难不给解法 = 差。</p></blockquote><hr><h2 id="_10-📌-面试前-1-天-checklist" tabindex="-1">10. 📌 面试前 1 天 checklist <a class="header-anchor" href="#_10-📌-面试前-1-天-checklist" aria-label="Permalink to &quot;10. 📌 面试前 1 天 checklist&quot;">​</a></h2><ul><li>[ ] <strong>自我介绍</strong> 掐表练 3 遍，卡在 <strong>1:50–2:10</strong></li><li>[ ] <strong>三个数字</strong> 确认：认识引荐人（<strong>X</strong>）个月 / 参加过（<strong>X</strong>）场活动 / 三个月目标（<strong>X</strong>）</li><li>[ ] <strong>A/B/C 客户名单</strong>列出（<strong>X</strong>）人，标好优先级</li><li>[ ] <strong>友邦功课</strong>：成立时间、内地进入年份、口号、2-3 条产品线、代理人制度特点</li><li>[ ] <strong>家庭口径</strong>和家人对过：收入预期 / 社保 / 时间 / 孩子谁带</li><li>[ ] <strong>挑战题</strong>选定 1 个，配套应对动作</li><li>[ ] <strong>优势</strong>只说 3 个，每个有证据</li><li>[ ] 反问准备 2-3 个</li></ul><hr><h2 id="_11-反问环节-别放过" tabindex="-1">11. 反问环节（别放过） <a class="header-anchor" href="#_11-反问环节-别放过" aria-label="Permalink to &quot;11. 反问环节（别放过）&quot;">​</a></h2><p>主管问完通常会问&quot;你有什么想问的&quot;。<strong>问得好 = 加分，问不到点 = 减分。</strong></p><h3 id="✅-值得问的-显示你在认真考虑这份事业" tabindex="-1">✅ 值得问的（显示你在认真考虑这份事业） <a class="header-anchor" href="#✅-值得问的-显示你在认真考虑这份事业" aria-label="Permalink to &quot;✅ 值得问的（显示你在认真考虑这份事业）&quot;">​</a></h3><ol><li>&quot;您团队现在有多少人？今年新人的留存情况怎么样？&quot; → 问留存 = 你想长期干，不是试水</li><li>&quot;您觉得一个新人前三个月，最关键的动作是什么？&quot; → 把自己放到&quot;想做好&quot;的姿态；<strong>顺便拿到主管的期望值</strong></li><li>&quot;团队里目前有（<strong>做家庭保障 / 做企业主</strong>）方向做得很好的人吗？ 方便的话我想了解一下团队里我将来能请教谁。&quot; → 表达谦逊 + 想融入团队</li><li>&quot;公司的培训体系是怎样的？有没有系统的增员辅导和活动支持？&quot; → 关心成长路径</li></ol><h3 id="❌-不要问" tabindex="-1">❌ 不要问 <a class="header-anchor" href="#❌-不要问" aria-label="Permalink to &quot;❌ 不要问&quot;">​</a></h3><ul><li>❌ 底薪多少、佣金多少（<strong>三面就谈钱 = 减分</strong>，留到终面/谈 offer）</li><li>❌ &quot;我能不能只做兼职&quot;（直接踩投入度）</li><li>❌ &quot;多久能出单&quot;（把代理当投资，问法就是错的）</li><li>❌ 跟产品收益细节打价格战</li></ul><blockquote><p>🎯 如果主管主动问你期望收入，可以答： &quot;我的目标是（<strong>你算的数</strong>），具体我更看重<strong>长期的路径</strong>——就像您团队的（<strong>某某</strong>）那样， 前期我愿意跟着您把基础打扎实。&quot;</p></blockquote><hr><h2 id="_12-面试后跟进" tabindex="-1">12. 面试后跟进 <a class="header-anchor" href="#_12-面试后跟进" aria-label="Permalink to &quot;12. 面试后跟进&quot;">​</a></h2><h3 id="当天" tabindex="-1">当天 <a class="header-anchor" href="#当天" aria-label="Permalink to &quot;当天&quot;">​</a></h3><ul><li>微信/短信简短致谢，<strong>不要长篇大论</strong></li><li>模板：&quot;XX 总您好，感谢今天的面试，也很感谢您讲的（<strong>提一个他说的具体内容</strong>）。</li></ul><blockquote><p>我回去后又把（<strong>某个具体问题</strong>）想了一下，我第一周的计划是（<strong>一句话</strong>）。期待您指导。&quot;</p></blockquote><h3 id="_3–5-天后-如果没消息" tabindex="-1">3–5 天后（如果没消息） <a class="header-anchor" href="#_3–5-天后-如果没消息" aria-label="Permalink to &quot;3–5 天后（如果没消息）&quot;">​</a></h3><ul><li>主动跟进一次，<strong>带增量信息</strong>（比如&quot;我这两天列完了第一批客户名单，A 类有 X 个&quot;）</li><li>只跟进一次。第二次不回就停</li></ul><hr><h2 id="_13-一页速记-临场只看这个" tabindex="-1">13. 一页速记（临场只看这个） <a class="header-anchor" href="#_13-一页速记-临场只看这个" aria-label="Permalink to &quot;13. 一页速记（临场只看这个）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题</th><th>核心动作</th><th>关键句</th></tr></thead><tbody><tr><td>1 自我介绍</td><td>2 分钟四段式</td><td>经历要<strong>接到风险/决策</strong>，不要背技术栈</td></tr><tr><td>2 引荐人</td><td>三个数字 + 观察</td><td>&quot;他们第一句问的是&#39;出事了怎么办&#39;&quot;</td></tr><tr><td>3 友邦了解</td><td>抄官方数字</td><td>把「健康长久好生活」翻译成业务理解</td></tr><tr><td>4 销售观/优势/挑战</td><td>3 个优势 + 1 个真挑战</td><td>挑战必须配应对动作</td></tr><tr><td>5 三个月目标</td><td>三档 + 逐月拆解</td><td>说&quot;我第一周就有第一次面谈&quot;</td></tr><tr><td>6 工作模式/拓客</td><td>双轮 + 四渠道 + 数量</td><td>&quot;每周 X 新增、每月 X 面谈&quot;</td></tr><tr><td>7 家庭支持</td><td>先说支持 + 再给安排</td><td>社保不断缴 + 目标已沟通</td></tr></tbody></table><blockquote><p><strong>三个致命词，烂熟于心：</strong><strong>数字</strong>（量化一切）· <strong>动作</strong>（落到可验证的下一步）· <strong>安排</strong>（家庭已谈妥）</p></blockquote><hr><h2 id="🔗-相关文章" tabindex="-1">🔗 相关文章 <a class="header-anchor" href="#🔗-相关文章" aria-label="Permalink to &quot;🔗 相关文章&quot;">​</a></h2><ul><li><a href="./01-酒会活动">一、酒会活动</a> —— 活动获客全流程</li><li><a href="./02-客户面谈">二、客户面谈</a> —— 需求分析</li><li><a href="./03-保障方案">三、保障方案</a> —— 方案设计</li><li><a href="./04-促成成交">四、促成成交</a> —— 促成与转介绍</li><li><a href="./05-获客转介绍">五、获客与转介绍</a> —— 客户分类管理</li></ul><hr><blockquote><p>💡 本篇里的所有（<strong>X</strong>）都是<strong>待填空</strong>。填完这版再上场， 不要带着模板去面试。</p></blockquote>',162)])])}const b=o(e,[["render",d]]);export{g as __pageData,b as default};
